insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('propuesta-de-rediseno-para-una-plaza-o-parque','ciudades',array['arte','ambiente']::text[],'Propuesta de rediseño para una plaza o parque','Elige una plaza o parque real, entiende cómo funciona hoy y diseña una propuesta de rediseño con zonas, vegetación, sombra, mobiliario y actividades.','Plan','3 a 5 semanas',28,array['Rediseño','Parques']::text[],array['crear']::text[],'propios',NULL,'arquitectura diseno ingenieria ambiental ingenieria civil geografia sociologia paisajismo ingenieria agroindustrial levantamiento de planos. diseno paisajista basico. representacion grafica. estimacion de costos. un programa de dibujo o planos. cinta metrica. hoja de calculo.',$a40sld${"id": "propuesta-de-rediseno-para-una-plaza-o-parque", "area": "ciudades", "areas2": ["arte", "ambiente"], "titulo": "Propuesta de rediseño para una plaza o parque", "resumen": "Elige una plaza o parque real, entiende cómo funciona hoy y diseña una propuesta de rediseño con zonas, vegetación, sombra, mobiliario y actividades.", "tipo": "Plan", "tiempo": "3 a 5 semanas", "horas": 28, "etiquetas": ["Rediseño", "Parques"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Diseño", "Ingeniería Ambiental", "Ingeniería Civil", "Geografía", "Sociología", "Paisajismo", "Ingeniería Agroindustrial"], "problema": ["Muchas plazas y parques se diseñaron hace décadas para necesidades distintas. Hoy pueden tener poca sombra, caminos mal ubicados o ningún lugar para estar cómodos.", "Rediseñarlos con una mirada de uso real, de clima y de comunidad es un buen ejercicio para aprender a proponer soluciones concretas."], "desarrollar": ["Haz un levantamiento del espacio: plano a mano con medidas aproximadas, árboles, caminos, bancas y usos, y un diagnóstico de qué funciona y qué no.", "Propón un nuevo plano con zonas bien pensadas, árboles y sombra, mobiliario y actividades, representa un antes y después, y estima los costos principales."], "ampliaciones": [{"titulo": "Riego y mantenimiento", "aporta": "estima el agua y el trabajo que requeriría el nuevo diseño."}, {"titulo": "Seguridad", "aporta": "revisa que el diseño tenga buena visibilidad y luz."}, {"titulo": "Etapas", "aporta": "divide la propuesta en etapas que se puedan financiar por separado."}], "objetivos": ["Hacer un levantamiento del espacio.", "Diagnosticar su funcionamiento.", "Diseñar una propuesta.", "Estimar costos y etapas."], "habilidades": ["Levantamiento de planos.", "Diseño paisajista básico.", "Representación gráfica.", "Estimación de costos."], "herramientas": ["Un programa de dibujo o planos.", "Cinta métrica.", "Hoja de cálculo."], "lineamientos": ["Presenta la propuesta como una idea y no como un proyecto oficial; no modifiques el espacio real sin autorización.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo proceso sirve para rediseñar un patio escolar, un jardín de un hospital o un espacio de un campus."}$a40sld$::jsonb,56),
('reimaginar-una-calle-para-peatones-y-ciclistas','ciudades',array['ambiente','arte']::text[],'Reimaginar una calle para peatones y ciclistas','Elige una calle de tu zona y diseña cómo se vería si diera más espacio a personas que caminan y van en bicicleta, sin dejar de atender a quienes necesitan vehículos.','Plan','~26 h',26,array['Calles','Movilidad activa']::text[],array['crear']::text[],'propios',NULL,'arquitectura ingenieria civil diseno geografia ingenieria ambiental sociologia ingenieria industrial economia diseno urbano basico. medicion en campo. analisis de efectos. comunicacion visual. un programa de dibujo. cinta metrica. hoja de calculo.',$a41sld${"id": "reimaginar-una-calle-para-peatones-y-ciclistas", "area": "ciudades", "areas2": ["ambiente", "arte"], "titulo": "Reimaginar una calle para peatones y ciclistas", "resumen": "Elige una calle de tu zona y diseña cómo se vería si diera más espacio a personas que caminan y van en bicicleta, sin dejar de atender a quienes necesitan vehículos.", "tipo": "Plan", "tiempo": "~26 h", "horas": 26, "etiquetas": ["Calles", "Movilidad activa"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Diseño", "Geografía", "Ingeniería Ambiental", "Sociología", "Ingeniería Industrial", "Economía"], "problema": ["Muchas calles se diseñaron para que pasen autos, y el espacio para peatones y ciclistas es lo que sobra. Pero las calles también son lugares para estar, comprar, jugar y encontrarse.", "Repensarlas con otras prioridades permite ver qué cambiaría y qué problemas habría que resolver."], "desarrollar": ["Elige una calle y mide su ancho total, el espacio de pista, veredas y estacionamientos, y observa quiénes la usan, cuántos vehículos, peatones y ciclistas pasan en horas distintas.", "Dibuja un diseño con un reparto distinto del espacio, con ciclovía, veredas más anchas, árboles y cruces, y analiza qué efectos tendría en el tránsito, el comercio y la seguridad."], "ampliaciones": [{"titulo": "Solo los fines de semana", "aporta": "propón cerrar la calle a vehículos en ciertos horarios."}, {"titulo": "Voz del comercio", "aporta": "pregunta a comerciantes qué les preocuparía del cambio."}, {"titulo": "Costo", "aporta": "estima cuánto costaría el rediseño por cuadra."}], "objetivos": ["Medir y observar una calle.", "Diseñar un reparto distinto del espacio.", "Analizar efectos y conflictos.", "Presentar la propuesta con claridad."], "habilidades": ["Diseño urbano básico.", "Medición en campo.", "Análisis de efectos.", "Comunicación visual."], "herramientas": ["Un programa de dibujo.", "Cinta métrica.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Presenta el diseño como una propuesta y reconoce las necesidades de quienes dependen de vehículos, como transporte de carga o personas con movilidad reducida."], "otroSector": "El mismo ejercicio sirve para repensar un estacionamiento, un patio escolar o un pasaje."}$a41sld$::jsonb,57),
('como-cambia-un-espacio-durante-el-dia','ciudades',array['sociedad']::text[],'¿Cómo cambia un espacio durante el día?','Observa un mismo lugar a distintas horas y describe cómo cambian quiénes lo usan, qué actividades ocurren y qué sensación produce.','Investigación','~18 h',18,array['Tiempo','Espacio público']::text[],array['investigar']::text[],'propios',NULL,'geografia sociologia arquitectura psicologia estadistica antropologia diseno comunicaciones observacion sistematica. visualizacion de datos. analisis cualitativo. pensamiento creativo. una ficha de observacion. un editor de graficos o infografias. hoja de calculo.',$a42sld${"id": "como-cambia-un-espacio-durante-el-dia", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Cómo cambia un espacio durante el día?", "resumen": "Observa un mismo lugar a distintas horas y describe cómo cambian quiénes lo usan, qué actividades ocurren y qué sensación produce.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Tiempo", "Espacio público"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Geografía", "Sociología", "Arquitectura", "Psicología", "Estadística", "Antropología", "Diseño", "Comunicaciones"], "problema": ["Una plaza a las siete de la mañana no es la misma que a mediodía o a la noche. Cambian las personas, los ruidos, la sombra, la seguridad y las actividades.", "Observar el ciclo completo ayuda a entender que un espacio cumple varios papeles y que un diseño pensado para una sola hora puede fallar en otras."], "desarrollar": ["Elige un lugar, como una esquina, un mercado o un parque, y regístralo en seis momentos del día durante tres días, con una ficha sobre cantidad de personas, tipos de actividades, ruido, luz y sensación general.", "Resume los cambios en una línea de tiempo visual, identifica las horas con más actividad o más riesgo y propón cómo el espacio podría aprovechar mejor sus horas muertas."], "ampliaciones": [{"titulo": "Fotografía de la luz", "aporta": "documenta el cambio de luz con fotos del mismo ángulo."}, {"titulo": "Fin de semana", "aporta": "compara con un día no laborable."}, {"titulo": "Mapa de sonidos", "aporta": "añade un registro de qué sonidos predominan en cada hora."}], "objetivos": ["Observar en distintos momentos.", "Registrar con una ficha.", "Resumir cambios visualmente.", "Proponer mejoras por horario."], "habilidades": ["Observación sistemática.", "Visualización de datos.", "Análisis cualitativo.", "Pensamiento creativo."], "herramientas": ["Una ficha de observación.", "Un editor de gráficos o infografías.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo estudio sirve para observar un comedor universitario, una estación o un hospital durante el día."}$a42sld$::jsonb,58),
('estudio-de-flujos-de-personas-en-un-espacio-publico','ciudades',array['tecnologia','sociedad']::text[],'Estudio de flujos de personas en un espacio público','Cuenta y analiza cómo circula la gente por un espacio público, por dónde entra y sale, dónde se detiene y dónde se forman aglomeraciones.','Análisis','~22 h',22,array['Flujos','Conteo']::text[],array['investigar']::text[],'propios',NULL,'ingenieria civil ingenieria industrial estadistica arquitectura matematica geografia ingenieria de sistemas ciencia de datos conteo y estadistica. diagramas de flujo. analisis espacial. propuestas de mejora. contadores manuales o una aplicacion de conteo. hoja de calculo. un programa de dibujo.',$a43sld${"id": "estudio-de-flujos-de-personas-en-un-espacio-publico", "area": "ciudades", "areas2": ["tecnologia", "sociedad"], "titulo": "Estudio de flujos de personas en un espacio público", "resumen": "Cuenta y analiza cómo circula la gente por un espacio público, por dónde entra y sale, dónde se detiene y dónde se forman aglomeraciones.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Flujos", "Conteo"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Industrial", "Estadística", "Arquitectura", "Matemática", "Geografía", "Ingeniería de Sistemas", "Ciencia de Datos"], "problema": ["Las personas no se distribuyen al azar: siguen caminos, evitan obstáculos y se concentran en ciertos puntos. Entender esos flujos ayuda a ubicar puertas, bancas, puestos y señales donde de verdad funcionan.", "El conteo con método es una técnica sencilla que se usa en urbanismo y en comercio."], "desarrollar": ["Elige un espacio con varios accesos, como una plaza o la entrada de un mercado, y cuenta durante periodos de cinco minutos cuántas personas pasan por cada acceso y en qué dirección, en distintos horarios.", "Dibuja un diagrama de flujos con flechas proporcionales, identifica los puntos de aglomeración y propón cambios de ubicación de elementos para mejorar la circulación."], "ampliaciones": [{"titulo": "Mapa de trayectorias", "aporta": "dibuja los caminos reales que siguen las personas, incluso los que no son oficiales."}, {"titulo": "Simulación", "aporta": "programa una simulación sencilla de personas caminando."}, {"titulo": "Capacidad", "aporta": "estima cuántas personas caben cómodamente en el espacio."}], "objetivos": ["Contar flujos con método.", "Representarlos en un diagrama.", "Identificar aglomeraciones.", "Proponer cambios."], "habilidades": ["Conteo y estadística.", "Diagramas de flujo.", "Análisis espacial.", "Propuestas de mejora."], "herramientas": ["Contadores manuales o una aplicación de conteo.", "Hoja de cálculo.", "Un programa de dibujo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo estudio sirve para ubicar puestos de un evento, circulación en un hospital o filas en un comedor."}$a43sld$::jsonb,59),
('mapa-participativo-de-tu-barrio','ciudades',array['sociedad','tecnologia']::text[],'Mapa participativo de tu barrio','Construye con vecinos un mapa del barrio que muestre lo que las personas valoran, lo que les preocupa y los lugares que consideran importantes, para ver el barrio con sus propios ojos.','Prototipo','3 a 4 semanas',24,array['Mapeo comunitario','Participación']::text[],array['crear','investigar']::text[],'propios',NULL,'geografia trabajo social sociologia ingenieria de sistemas arquitectura antropologia comunicaciones educacion mapeo participativo. facilitacion de grupos. analisis cualitativo. comunicacion a la comunidad. papel o un mapa en linea. marcadores o pegatinas. un editor de diseno.',$a44sld${"id": "mapa-participativo-de-tu-barrio", "area": "ciudades", "areas2": ["sociedad", "tecnologia"], "titulo": "Mapa participativo de tu barrio", "resumen": "Construye con vecinos un mapa del barrio que muestre lo que las personas valoran, lo que les preocupa y los lugares que consideran importantes, para ver el barrio con sus propios ojos.", "tipo": "Prototipo", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Mapeo comunitario", "Participación"], "intencion": ["crear", "investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Geografía", "Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Arquitectura", "Antropología", "Comunicaciones", "Educación"], "problema": ["Los mapas oficiales muestran calles y manzanas, pero no dicen dónde se juega, qué lugares dan miedo o dónde se conversa. Esa información solo la tienen quienes viven allí.", "Un mapa participativo reúne esos saberes y permite conversar sobre el barrio con evidencia propia."], "desarrollar": ["Diseña una dinámica simple, como un mapa en papel o una hoja de marcadores, donde cada participante ubique lugares que le gustan, que le preocupan y que usa a diario.", "Reúne los mapas de al menos diez personas, combínalos en uno solo, identifica coincidencias y diferencias y presenta el resultado a la comunidad como punto de partida de una conversación."], "ampliaciones": [{"titulo": "Versión digital", "aporta": "convierte el mapa en una página web interactiva."}, {"titulo": "Por edades", "aporta": "compara cómo mapean el barrio niños, jóvenes y personas mayores."}, {"titulo": "Historias", "aporta": "añade breves historias asociadas a algunos lugares."}], "objetivos": ["Diseñar una dinámica participativa.", "Combinar mapas individuales.", "Analizar coincidencias y diferencias.", "Presentar resultados a la comunidad."], "habilidades": ["Mapeo participativo.", "Facilitación de grupos.", "Análisis cualitativo.", "Comunicación a la comunidad."], "herramientas": ["Papel o un mapa en línea.", "Marcadores o pegatinas.", "Un editor de diseño."], "lineamientos": ["La participación debe ser voluntaria, con consentimiento informado; no registres nombres ni direcciones exactas.", "Evita marcar viviendas concretas y respeta lugares que algunas personas no quieran compartir."], "otroSector": "El mismo método sirve para mapear un colegio, una universidad o un lugar de trabajo con quienes lo usan."}$a44sld$::jsonb,60),
('que-necesidades-urbanas-perciben-los-vecinos-y-que-cambiarian-de','ciudades',array['sociedad','derecho']::text[],'¿Qué necesidades urbanas perciben los vecinos y qué cambiarían de sus espacios comunes?','Pregunta a quienes viven en un barrio qué problemas notan y qué cambiarían en sus espacios comunes, y ordena sus respuestas para ver qué necesidades son las más compartidas.','Investigación','~22 h',22,array['Necesidades','Participación']::text[],array['investigar']::text[],'propios',NULL,'sociologia trabajo social arquitectura ciencias politicas estadistica geografia psicologia derecho diseno de encuestas. analisis de texto simple. estadistica descriptiva. comunicacion clara. un formulario anonimo. hoja de calculo. un editor de infografias.',$a45sld${"id": "que-necesidades-urbanas-perciben-los-vecinos-y-que-cambiarian-de", "area": "ciudades", "areas2": ["sociedad", "derecho"], "titulo": "¿Qué necesidades urbanas perciben los vecinos y qué cambiarían de sus espacios comunes?", "resumen": "Pregunta a quienes viven en un barrio qué problemas notan y qué cambiarían en sus espacios comunes, y ordena sus respuestas para ver qué necesidades son las más compartidas.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Necesidades", "Participación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Trabajo Social", "Arquitectura", "Ciencias Políticas", "Estadística", "Geografía", "Psicología", "Derecho"], "problema": ["Quien vive en un barrio sabe cuáles son sus problemas, pero esa voz rara vez llega a quienes toman decisiones. Y lo que preocupa a unos no siempre es lo que preocupa a otros.", "Preguntar de forma ordenada permite distinguir entre quejas aisladas y necesidades compartidas."], "desarrollar": ["Diseña una encuesta anónima con preguntas abiertas y cerradas sobre los espacios comunes del barrio, como qué les gusta, qué les molesta y qué cambiarían, y aplícala a una muestra pequeña.", "Clasifica las respuestas por temas, calcula cuántas personas mencionan cada uno, contrasta con los problemas que tú observaste y prepara un resumen con las cinco necesidades más urgentes."], "ampliaciones": [{"titulo": "Prioridades", "aporta": "pide que ordenen los problemas por importancia."}, {"titulo": "Distintos grupos", "aporta": "compara lo que dicen jóvenes, adultos y personas mayores."}, {"titulo": "Devolución", "aporta": "organiza una breve reunión para mostrar los resultados."}], "objetivos": ["Diseñar una encuesta abierta y cerrada.", "Clasificar respuestas por temas.", "Identificar necesidades compartidas.", "Comunicar resultados."], "habilidades": ["Diseño de encuestas.", "Análisis de texto simple.", "Estadística descriptiva.", "Comunicación clara."], "herramientas": ["Un formulario anónimo.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["La encuesta debe ser anónima y voluntaria; no incluyas preguntas sobre conflictos con personas concretas.", "Presenta los resultados como tendencias de una muestra pequeña."], "otroSector": "El mismo método sirve para recoger las necesidades de estudiantes de un colegio, usuarios de una biblioteca o trabajadores de una empresa."}$a45sld$::jsonb,61),
('oportunidades-de-mejora-urbana-mediante-observacion','ciudades',array['sociedad']::text[],'Oportunidades de mejora urbana mediante observación','Aprende a mirar tu entorno como un diagnosticador urbano: recorre una zona con una ficha de observación y detecta pequeñas mejoras que cambiarían el uso del espacio.','Análisis','~18 h',18,array['Observación','Diagnóstico urbano']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura geografia ingenieria civil sociologia diseno ingenieria ambiental trabajo social antropologia observacion sistematica. priorizacion. diseno de fichas. propuestas de mejora. una ficha de observacion. un mapa en linea. hoja de calculo.',$a46sld${"id": "oportunidades-de-mejora-urbana-mediante-observacion", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Oportunidades de mejora urbana mediante observación", "resumen": "Aprende a mirar tu entorno como un diagnosticador urbano: recorre una zona con una ficha de observación y detecta pequeñas mejoras que cambiarían el uso del espacio.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Observación", "Diagnóstico urbano"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Geografía", "Ingeniería Civil", "Sociología", "Diseño", "Ingeniería Ambiental", "Trabajo Social", "Antropología"], "problema": ["Muchas mejoras urbanas no necesitan grandes obras: un cruce pintado, una banca, una rampa o una luz pueden cambiar mucho. Pero hay que aprender a ver qué hace falta.", "La observación sistemática entrena esa mirada y produce una lista de oportunidades concretas."], "desarrollar": ["Recorre una zona de entre cinco y diez cuadras con una ficha que incluya aspectos como seguridad, comodidad, accesibilidad, belleza y uso, y puntúa cada tramo.", "Identifica las diez oportunidades de mejora más claras, clasifícalas por costo y por efecto, y presenta las tres con mejor relación entre ambos."], "ampliaciones": [{"titulo": "Comparar observadores", "aporta": "haz que dos personas recorran la misma zona y compara."}, {"titulo": "Medir el cambio", "aporta": "elige una mejora pequeña, aplícala con permiso y observa su efecto."}, {"titulo": "Álbum visual", "aporta": "crea un álbum de antes y después con dibujos de las propuestas."}], "objetivos": ["Diseñar una ficha de observación.", "Detectar oportunidades concretas.", "Clasificar por costo y efecto.", "Priorizar propuestas."], "habilidades": ["Observación sistemática.", "Priorización.", "Diseño de fichas.", "Propuestas de mejora."], "herramientas": ["Una ficha de observación.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "No ejecutes cambios en el espacio público sin autorización; presenta tus ideas como propuestas."], "otroSector": "La misma mirada sirve para detectar mejoras en un campus, una tienda o un puesto de trabajo."}$a46sld$::jsonb,62),
('inventario-de-infraestructura-comunitaria','ciudades',array['sociedad']::text[],'Inventario de infraestructura comunitaria','Registra qué infraestructura de uso colectivo existe en una comunidad, como locales comunales, losas deportivas, postas o parques, en qué estado está y a quién sirve.','Análisis','~20 h',20,array['Inventario','Comunidad']::text[],array['investigar']::text[],'propios',NULL,'ingenieria civil arquitectura geografia trabajo social sociologia estadistica administracion ingenieria de sistemas inventario en campo. organizacion de datos. cartografia basica. priorizacion. una ficha de inventario. hoja de calculo. un mapa en linea.',$a47sld${"id": "inventario-de-infraestructura-comunitaria", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Inventario de infraestructura comunitaria", "resumen": "Registra qué infraestructura de uso colectivo existe en una comunidad, como locales comunales, losas deportivas, postas o parques, en qué estado está y a quién sirve.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Inventario", "Comunidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Arquitectura", "Geografía", "Trabajo Social", "Sociología", "Estadística", "Administración", "Ingeniería de Sistemas"], "problema": ["Una comunidad no siempre sabe con qué infraestructura cuenta ni en qué estado está. Sin un inventario, es difícil pedir mejoras, planificar su uso o cuidarla.", "Hacerlo con una ficha ordenada permite ver qué hay, qué falta y qué necesita mantenimiento."], "desarrollar": ["Diseña una ficha para registrar cada elemento de infraestructura comunitaria con su tipo, ubicación general, estado, usos y quién lo administra, y recorre una zona completando la ficha.", "Resume el inventario en tablas y mapas, identifica los elementos en peor estado o poco utilizados y propón qué elementos hacen falta."], "ampliaciones": [{"titulo": "Actualización", "aporta": "diseña un sistema para mantener el inventario al día."}, {"titulo": "Costo de mantenimiento", "aporta": "estima cuánto costaría reparar lo que está en mal estado."}, {"titulo": "Uso real", "aporta": "compara el uso real con el uso planificado de cada elemento."}], "objetivos": ["Diseñar una ficha de inventario.", "Registrar la infraestructura de una zona.", "Resumir en tablas y mapas.", "Identificar prioridades."], "habilidades": ["Inventario en campo.", "Organización de datos.", "Cartografía básica.", "Priorización."], "herramientas": ["Una ficha de inventario.", "Hoja de cálculo.", "Un mapa en línea."], "lineamientos": ["Registra solo infraestructura de uso público o comunitario, con permiso de quien la administre, y no datos de propiedades privadas.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo inventario sirve para un colegio, un campus, un hospital o un parque industrial."}$a47sld$::jsonb,63),
('comercio-local-y-uso-del-espacio-publico','ciudades',array['negocios','derecho']::text[],'Comercio local y uso del espacio público','Estudia cómo conviven los comercios, los vendedores y los peatones en una calle o plaza, y qué tensiones y beneficios genera el uso comercial del espacio público.','Investigación','~22 h',22,array['Comercio','Espacio público']::text[],array['investigar']::text[],'propios',NULL,'economia derecho sociologia arquitectura geografia administracion trabajo social ciencias politicas observacion de campo. entrevistas. lectura de normas. propuesta de soluciones. cinta metrica. guia de entrevista. un programa de dibujo.',$a48sld${"id": "comercio-local-y-uso-del-espacio-publico", "area": "ciudades", "areas2": ["negocios", "derecho"], "titulo": "Comercio local y uso del espacio público", "resumen": "Estudia cómo conviven los comercios, los vendedores y los peatones en una calle o plaza, y qué tensiones y beneficios genera el uso comercial del espacio público.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Comercio", "Espacio público"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Derecho", "Sociología", "Arquitectura", "Geografía", "Administración", "Trabajo Social", "Ciencias Políticas"], "problema": ["Veredas con mesas, vendedores ambulantes, mercados informales y ferias dan vida y empleo a una zona, pero también reducen el espacio para caminar. Distintas personas defienden usos distintos del mismo lugar.", "Entender esas tensiones permite proponer soluciones que no perjudiquen a ninguno de los grupos."], "desarrollar": ["Elige una calle o plaza con presencia de comercio y mide cuánto ancho de vereda ocupa el comercio, cuánto queda libre, cuántos puestos hay y qué horas funcionan.", "Conversa con cuatro actores distintos, como un comerciante, un peatón, un vecino y un trabajador municipal, sobre sus necesidades, y propón un reparto del espacio que equilibre usos."], "ampliaciones": [{"titulo": "Marco normativo", "aporta": "revisa qué dicen las ordenanzas sobre el uso comercial del espacio público."}, {"titulo": "Beneficios económicos", "aporta": "estima cuánto dinero y empleo genera el comercio de la zona."}, {"titulo": "Diseño del reparto", "aporta": "dibuja una propuesta de ordenamiento con módulos o zonas."}], "objetivos": ["Medir el uso comercial del espacio.", "Escuchar a distintos actores.", "Entender normas.", "Proponer un reparto equilibrado."], "habilidades": ["Observación de campo.", "Entrevistas.", "Lectura de normas.", "Propuesta de soluciones."], "herramientas": ["Cinta métrica.", "Guía de entrevista.", "Un programa de dibujo."], "lineamientos": ["Pide consentimiento para entrevistar y no expongas a vendedores sin permiso ni señales sus faltas.", "Presenta tu análisis de forma neutral, sin juzgar a ningún grupo."], "otroSector": "El mismo análisis sirve para estudiar el uso de espacios compartidos en un campus, un mercado o una estación."}$a48sld$::jsonb,64),
('donde-se-concentran-los-servicios-de-tu-barrio-y-que-tan-facil-e','ciudades',array['sociedad','negocios']::text[],'¿Dónde se concentran los servicios de tu barrio y qué tan fácil es encontrarlos?','Mapea los servicios esenciales de tu barrio, como farmacias, bancos, centros de salud, colegios y mercados, y evalúa qué tan cerca y fáciles de encontrar están.','Análisis','~20 h',20,array['Servicios','Mapa']::text[],array['investigar','crear']::text[],'propios',NULL,'geografia economia sociologia arquitectura ingenieria de sistemas estadistica administracion trabajo social inventario de campo. cartografia basica. calculo de distancias. diseno de guias. una ficha de registro. un mapa en linea. hoja de calculo.',$a49sld${"id": "donde-se-concentran-los-servicios-de-tu-barrio-y-que-tan-facil-e", "area": "ciudades", "areas2": ["sociedad", "negocios"], "titulo": "¿Dónde se concentran los servicios de tu barrio y qué tan fácil es encontrarlos?", "resumen": "Mapea los servicios esenciales de tu barrio, como farmacias, bancos, centros de salud, colegios y mercados, y evalúa qué tan cerca y fáciles de encontrar están.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Servicios", "Mapa"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Geografía", "Economía", "Sociología", "Arquitectura", "Ingeniería de Sistemas", "Estadística", "Administración", "Trabajo Social"], "problema": ["Los servicios no se reparten por igual: algunas calles tienen de todo y otras casi nada. Además, a veces existen pero no son fáciles de encontrar por falta de señales o de información.", "Mapearlos permite ver dónde se concentran y dónde faltan, y qué tan fácil es llegar."], "desarrollar": ["Recorre una zona y registra cada negocio y servicio esencial con su tipo y ubicación aproximada, y clasifícalos en categorías como salud, alimentación, educación, finanzas y trámites.", "Haz un mapa por categoría, calcula la distancia a pie desde varios puntos del barrio a cada servicio y pregunta a cinco personas qué tan fácil les resulta encontrarlos."], "ampliaciones": [{"titulo": "Servicios que faltan", "aporta": "identifica qué servicio no existe en la zona y cuánto habría que caminar."}, {"titulo": "Horarios", "aporta": "añade en qué horas está disponible cada servicio."}, {"titulo": "Guía del barrio", "aporta": "elabora una guía ilustrada para nuevos vecinos."}], "objetivos": ["Registrar servicios con método.", "Mapearlos por categorías.", "Calcular distancias.", "Detectar servicios faltantes."], "habilidades": ["Inventario de campo.", "Cartografía básica.", "Cálculo de distancias.", "Diseño de guías."], "herramientas": ["Una ficha de registro.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Registra solo establecimientos públicos y sus tipos, y no datos de las personas que trabajan ahí.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo mapa sirve para ubicar servicios dentro de un campus, un hospital o un parque industrial."}$a49sld$::jsonb,65),
('distribucion-de-comercios-y-actividad-comercial-en-una-zona','ciudades',array['negocios','sociedad']::text[],'Distribución de comercios y actividad comercial en una zona','Analiza cómo están distribuidos los comercios de una zona, dónde se concentra la actividad y qué factores explican que ciertas calles tengan más movimiento comercial.','Análisis','~22 h',22,array['Comercio','Actividad económica']::text[],array['investigar']::text[],'propios',NULL,'economia geografia administracion marketing arquitectura estadistica sociologia ingenieria industrial observacion y conteo. cartografia. analisis economico basico. interpretacion de resultados. una ficha de conteo. un mapa en linea. hoja de calculo.',$a50sld${"id": "distribucion-de-comercios-y-actividad-comercial-en-una-zona", "area": "ciudades", "areas2": ["negocios", "sociedad"], "titulo": "Distribución de comercios y actividad comercial en una zona", "resumen": "Analiza cómo están distribuidos los comercios de una zona, dónde se concentra la actividad y qué factores explican que ciertas calles tengan más movimiento comercial.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Comercio", "Actividad económica"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Geografía", "Administración", "Marketing", "Arquitectura", "Estadística", "Sociología", "Ingeniería Industrial"], "problema": ["Ciertas calles concentran tiendas, restaurantes y servicios, mientras otras están casi vacías. Eso depende del flujo de gente, del transporte, de la seguridad, de las normas y de cómo se agrupan los negocios.", "Entender esos patrones ayuda a decidir dónde conviene abrir un negocio y qué zonas necesitan impulso."], "desarrollar": ["Recorre varias calles y cuenta cuántos locales hay por cuadra, de qué tipo y cuántos están cerrados o en alquiler, y mide el flujo de peatones en horas clave.", "Haz un mapa de intensidad comercial, relaciona el resultado con el flujo de personas y el transporte cercano, y explica por qué algunas calles son más activas."], "ampliaciones": [{"titulo": "Tipos de negocios", "aporta": "analiza qué tipos tienden a agruparse y por qué."}, {"titulo": "Locales vacíos", "aporta": "estudia dónde hay más locales cerrados y qué podría explicarlo."}, {"titulo": "Un negocio nuevo", "aporta": "recomienda dónde abrir un negocio de un tipo dado y justifica."}], "objetivos": ["Contar y clasificar locales.", "Medir flujo de peatones.", "Mapear la actividad comercial.", "Explicar los patrones."], "habilidades": ["Observación y conteo.", "Cartografía.", "Análisis económico básico.", "Interpretación de resultados."], "herramientas": ["Una ficha de conteo.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Registra solo establecimientos visibles desde la vía pública y no datos de ventas ni de propietarios.", "No uses tus resultados para señalar a negocios concretos como buenos o malos."], "otroSector": "El mismo análisis sirve para ubicar un puesto en una feria, un kiosco en un campus o una tienda en un centro comercial."}$a50sld$::jsonb,66),
('comercio-y-movimiento-peatonal-como-se-influyen','ciudades',array['negocios','sociedad']::text[],'Comercio y movimiento peatonal: ¿cómo se influyen?','Investiga si las calles con más comercio atraen más peatones, o si más peatones atraen más comercio, y cómo cambia el movimiento a lo largo de una avenida comercial.','Investigación','~20 h',20,array['Comercio','Peatones']::text[],array['investigar']::text[],'propios',NULL,'economia geografia arquitectura marketing estadistica sociologia administracion ingenieria industrial conteo en campo. estadistica basica. graficos de dispersion. pensamiento critico. contadores manuales. hoja de calculo. un editor de graficos.',$a51sld${"id": "comercio-y-movimiento-peatonal-como-se-influyen", "area": "ciudades", "areas2": ["negocios", "sociedad"], "titulo": "Comercio y movimiento peatonal: ¿cómo se influyen?", "resumen": "Investiga si las calles con más comercio atraen más peatones, o si más peatones atraen más comercio, y cómo cambia el movimiento a lo largo de una avenida comercial.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Comercio", "Peatones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Geografía", "Arquitectura", "Marketing", "Estadística", "Sociología", "Administración", "Ingeniería Industrial"], "problema": ["Los negocios necesitan gente que pase, y la gente pasa donde hay cosas por hacer. Pero esa relación no es automática: depende del tipo de negocios, de la seguridad y de la comodidad de caminar.", "Conocer cómo se influyen ayuda a planear tanto calles comerciales como la ubicación de nuevos negocios."], "desarrollar": ["Elige dos o tres calles con distinta cantidad de comercios y cuenta cuántas personas pasan por tramos de cinco minutos en distintos horarios, junto con el número de locales abiertos en cada tramo.", "Relaciona ambos datos con un gráfico de dispersión, calcula la relación entre ellos y discute qué otros factores podrían explicar las diferencias."], "ampliaciones": [{"titulo": "Hora del día", "aporta": "analiza cómo cambia la relación entre la mañana y la noche."}, {"titulo": "Tipo de comercio", "aporta": "compara cómo influyen las tiendas, los restaurantes y los servicios."}, {"titulo": "Efecto de una mejora", "aporta": "estudia qué pasó con el comercio tras una mejora de vereda en la zona."}], "objetivos": ["Contar peatones y comercios.", "Relacionar ambos datos.", "Interpretar correlaciones con cuidado.", "Discutir otros factores."], "habilidades": ["Conteo en campo.", "Estadística básica.", "Gráficos de dispersión.", "Pensamiento crítico."], "herramientas": ["Contadores manuales.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Recuerda que correlación no es causa: presenta tus conclusiones como hipótesis."], "otroSector": "El mismo estudio sirve para evaluar cómo un evento o una obra cambia el movimiento de una zona."}$a51sld$::jsonb,67),
('comparando-dos-barrios-desde-la-perspectiva-de-infraestructura','ciudades',array['sociedad']::text[],'Comparando dos barrios desde la perspectiva de infraestructura','Compara dos barrios con una misma ficha de criterios sobre veredas, pistas, agua, luz, áreas verdes y servicios, para ver qué diferencias hay y por qué.','Análisis','3 a 4 semanas',24,array['Comparación','Barrios']::text[],array['investigar']::text[],'propios',NULL,'geografia ingenieria civil arquitectura sociologia estadistica economia trabajo social ingenieria ambiental diseno de indicadores. observacion sistematica. analisis comparativo. comunicacion de resultados. una ficha de evaluacion. hoja de calculo. datos publicos.',$a52sld${"id": "comparando-dos-barrios-desde-la-perspectiva-de-infraestructura", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Comparando dos barrios desde la perspectiva de infraestructura", "resumen": "Compara dos barrios con una misma ficha de criterios sobre veredas, pistas, agua, luz, áreas verdes y servicios, para ver qué diferencias hay y por qué.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Comparación", "Barrios"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Geografía", "Ingeniería Civil", "Arquitectura", "Sociología", "Estadística", "Economía", "Trabajo Social", "Ingeniería Ambiental"], "problema": ["Dos barrios de la misma ciudad pueden tener infraestructuras muy distintas, y esa diferencia influye en la calidad de vida de quienes viven allí. Compararlos con un método común permite ver las brechas con claridad.", "También ayuda a entender qué características del entorno, como la historia o el nivel de inversión, explican esas diferencias."], "desarrollar": ["Diseña una ficha con entre diez y quince indicadores de infraestructura y aplícala en dos barrios, mediante observación y datos públicos, con el mismo procedimiento en ambos.", "Compara en una tabla y un gráfico, explica las brechas, investiga posibles causas y propón qué mejoras reducirían la diferencia."], "ampliaciones": [{"titulo": "Tercer barrio", "aporta": "añade un tercer barrio y compara."}, {"titulo": "Inversión pública", "aporta": "relaciona las diferencias con el gasto municipal en cada zona."}, {"titulo": "Voz de los vecinos", "aporta": "contrasta tus indicadores con la percepción de quienes viven allí."}], "objetivos": ["Diseñar una ficha de indicadores.", "Aplicarla de forma equivalente.", "Comparar y explicar brechas.", "Proponer mejoras."], "habilidades": ["Diseño de indicadores.", "Observación sistemática.", "Análisis comparativo.", "Comunicación de resultados."], "herramientas": ["Una ficha de evaluación.", "Hoja de cálculo.", "Datos públicos."], "lineamientos": ["Evita etiquetar a los barrios como mejores o peores: describe diferencias de infraestructura y no de personas.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "La misma comparación sirve para colegios, hospitales o campus de distintas zonas."}$a52sld$::jsonb,68)
